                    );
                  },
                ),
              ),
              // News section
              Padding(
                padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
                child: Text(
                  loc.news,
                  style: context.fonts.semiBold14,
                ),
              ),
              ...news.map((NewsModel n) {
                return Padding(
                  key: ValueKey(n.link),
                  padding: const EdgeInsets.fromLTRB(22, 0, 22, 8),
                  child: NewsCard(model: n),
                );
              }),
            ],
          );
        },
      ),
    );
  }
}

class _DashboardCurrencyItem extends StatelessWidget {
  const _DashboardCurrencyItem({required this.model});

  final CurrencyModel model;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;
    final ThemeFonts fonts = context.fonts;
    final PriceChange priceChange = model.asPriceChange;

    return Container(
      padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 12),
      decoration: BoxDecoration(
        color: colors.cardColor,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          Container(
            constraints: BoxConstraints.tight(Size.square(30)),
            decoration: BoxDecoration(
              color: colors.currencyCardSymbolBackground,
              shape: BoxShape.circle,
            ),
            child: Center(
              child: Text(
                model.symbol,
                style: fonts.semiBold12.copyWith(color: Colors.white),
              ),
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              model.name,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: fonts.semiBold12,
            ),
          ),
          Text(
            model.value.toStringAsFixed(2),
            style: fonts.semiBold14.copyWith(
              color: switch (priceChange) {
                PriceChange.up => colors.greenWrasse,
                PriceChange.down => colors.red,
                PriceChange.stable => colors.stormyGrey,
              },
            ),
          ),
        ],
      ),
    );
  }
}

extension on CurrencyModel {
  PriceChange get asPriceChange {
    if (value > previousValue) return PriceChange.up;
    if (value < previousValue) return PriceChange.down;
    return PriceChange.stable;
  }
}
