  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;
    final ThemeFonts fonts = context.fonts;
    final _PriceChange priceChange = model.asPriceChange;

    return Container(
      padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 12),
      decoration: BoxDecoration(
        color: colors.cardColor,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          Container(
            constraints: BoxConstraints.tight(Size.square(30)),
            decoration: BoxDecoration(
              color: colors.currencyCardSymbolBackground,
              shape: BoxShape.circle,
            ),
            child: Center(
              child: Text(
                model.symbol,
                style: fonts.semiBold12.copyWith(color: Colors.white),
              ),
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              model.name,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: fonts.semiBold12,
            ),
          ),
          Text(
            model.value.toStringAsFixed(2),
            style: fonts.regular16.copyWith(
              fontWeight: FontWeight.w700,
              color: switch (priceChange) {
                _PriceChange.up => colors.greenWrasse,
                _PriceChange.down => colors.red,
                _PriceChange.stable => colors.stormyGrey,
              },
            ),
          ),
        ],
      ),
    );
  }
}

extension on CurrencyModel {
  _PriceChange get asPriceChange {
    if (value > previousValue) return _PriceChange.up;
    if (value < previousValue) return _PriceChange.down;
    return _PriceChange.stable;
  }
}
